builder.Services.AddSingleton(tempTrainer);
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(tempTrainer.ModelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

